def penalties_to_sar(apps, schema_editor):
    """Denda kini selalu SAR. Baris lama bermata uang lain memakai nilai SAR
    yang sudah tersimpan (amount_sar) sebagai nominalnya. Nominal 0 tidak sah:
    dilaporkan, tidak ditebak."""
    Penalty = apps.get_model('hw', 'CancellationPenalty')
    bad = []
    for p in Penalty.objects.all():
        amount = p.penalty_amount if p.penalty_currency == 'SAR' else (p.amount_sar or 0)
        if amount <= 0:
            bad.append(p.penalty_number)
        elif amount != p.penalty_amount:
            Penalty.objects.filter(pk=p.pk).update(penalty_amount=amount)
    if bad:
        raise RuntimeError('Denda bernilai 0 atau tanpa nilai SAR, perbaiki dulu: ' + ', '.join(bad))
    settle_constraints(schema_editor)


def attachments_have_one_parent(apps, schema_editor):
    Attachment = apps.get_model('hw', 'Attachment')
    both = Attachment.objects.filter(invoice__isnull=False, cl__isnull=False)
    neither = Attachment.objects.filter(invoice__isnull=True, cl__isnull=True)
    if both.exists() or neither.exists():
        ids = list(both.values_list('pk', flat=True)) + list(neither.values_list('pk', flat=True))
        raise RuntimeError(f'Lampiran tanpa induk tunggal (id {ids[:20]}), perbaiki dulu.')


